#include <iostream>
using namespace std;

void geser(int &x, int &y, char arah, int langkah) {
    if (arah == 'U') {
        y += langkah;
    } else if (arah == 'S') {
        y -= langkah;
    } else if (arah == 'T') {
        x += langkah;
    } else {
        x -= langkah;
    }
}

int main() {
    int x, y, n, langkah;
    char arah;
    cin >> x >> y;
    cin >> n;
    for (int k = 0; k < n; k++) {
        cin >> arah >> langkah;
        geser(x, y, arah, langkah);
    }
    cout << x << " " << y << endl;
    return 0;
}

