string keBasis(int n, int basis) {
    if (n == 0) {
        return "0";
    }
    string hasil = "";
    while (n > 0) {
        int d = n % basis;
        char c;
        if (d < 10) {
            c = (char) ('0' + d);
        } else {
            c = (char) ('A' + d - 10);
        }
        hasil = c + hasil;
        n /= basis;
    }
    return hasil;
}

