bool luhn(string nomor) {
    int jumlah = 0;
    bool gandakan = false;
    for (int k = (int) nomor.size() - 1; k >= 0; k--) {
        int d = nomor[k] - '0';
        if (gandakan) {
            d = d * 2;
            if (d > 9) {
                d -= 9;
            }
        }
        jumlah += d;
        gandakan = !gandakan;
    }
    return jumlah % 10 == 0;
}

int main() {
    string nomor;
    cin >> nomor;
    if (luhn(nomor)) {
        cout << "sah" << endl;
    } else {
        cout << "tidak sah" << endl;
    }
