}

#include <iostream>
#include <string>
using namespace std;

int nilai(char c) {
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        default: return 1000;
    }
}

int main() {
    string s;
    cin >> s;
    int n = s.size();
    int hasil = 0;
    for (int k = 0; k < n; k++) {
        if (k + 1 < n && nilai(s[k]) < nilai(s[k + 1])) {
            hasil -= nilai(s[k]);
        } else {
            hasil += nilai(s[k]);
        }
    }
    cout << hasil << endl;
    return 0;
}
